/* MODULE kn11 · Bước 5 Chọn kênh · Tìm kiếm tự nhiên (SEO) cho người mới
   8 bài × 7 câu. Đối chiếu nguồn (kiểm 10/2026): Google Search Central — SEO Starter Guide, How Search works,
   Creating helpful, reliable, people-first content, Spam policies; Search Console Help (Performance report);
   Google Business Profile Help (local ranking); Maps user-contributed content policy; Google Ads Help (Keyword Planner).
   Mọi con số là MINH HOẠ và tự khớp nhau. CTR theo vị trí là GIẢ ĐỊNH minh hoạ, không phải số liệu Google công bố. */
BAI_ADD({ mod:'kn11', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:kn11-01', skill:'channel', read:'6 phút', t:'Tắt quảng cáo Google là hết khách — có cách nào để khách vẫn tìm thấy shop?',
  situation:'Một tiệm bánh kem ở quận 7, TP.HCM chạy quảng cáo tìm kiếm Google, mỗi tháng khoảng 2.500 lượt nhấp, trung bình 3.200đ mỗi nhấp. Tháng nào hết ngân sách, đơn đặt online gần như về 0. Một agency chào gói "cam kết top 1 Google trong 2 tuần" giá 15 triệu. Chủ tiệm hỏi: SEO là gì, có nên mua gói này không? (số minh hoạ)',
  concept:{ name:'Tìm kiếm tự nhiên (SEO) và tìm kiếm trả tiền',
    body:'Trang kết quả Google có hai phần: <b>quảng cáo</b> (gắn nhãn "Được tài trợ", trả tiền theo lượt nhấp — nhiều người gọi là SEM, có nơi dùng SEM bao cả hai) và <b>kết quả tự nhiên</b> (organic, không trả tiền cho mỗi nhấp). SEO (search engine optimization, tối ưu cho công cụ tìm kiếm) là làm cho trang dễ được Google tìm thấy, hiểu và chọn hiển thị ở phần tự nhiên. Google chạy ba bước: thu thập (crawl), lập chỉ mục (index), trả kết quả — và nói rõ không nhận tiền để xếp hạng cao hơn. Theo SEO Starter Guide, thay đổi có thể có tác dụng sau vài giờ đến vài tháng, và không ai bảo đảm được vị trí. SEO chậm nhưng tích luỹ; quảng cáo dừng tiền là dừng nhấp. (Google Search Central, kiểm 10/2026)' },
  example:'Tiệm tính: 2.500 nhấp × 3.200đ = 8 triệu mỗi tháng cho quảng cáo, dừng là mất. Song song, tiệm làm một trang "bánh kem sinh nhật giao trong 2 giờ ở quận 7" có giá, ảnh bánh thật, giờ giao, và cập nhật hồ sơ Google Business. Tiệm giữ quảng cáo trong lúc chờ, vì trang mới có thể mất nhiều tuần đến vài tháng mới có nhấp đều. Gói "top 1 trong 2 tuần" bị từ chối: không ai bảo đảm được thứ hạng, và cách làm nhanh thường dựa vào mua liên kết — thứ Google xếp vào spam.',
  takeaway:'Quảng cáo là thuê chỗ, SEO là xây chỗ: chậm hơn, không ai bảo đảm thứ hạng, nhưng giá trị tích luỹ.',
  apply:'Tiệm có 8 triệu/tháng. Phương án A: dồn hết vào quảng cáo tìm kiếm. Phương án B: 5 triệu quảng cáo + 3 triệu làm 2 trang sản phẩm chi tiết mỗi tháng. Viết 3 câu khuyên chủ tiệm cho 6 tháng tới. Đạt khi: (1) nói rõ cái giá của B ở những tháng đầu, (2) không hứa thứ hạng hay ngày lên top, (3) nêu một chỉ số để theo dõi B.',
  mistakes:['Mua gói "cam kết top 1" — không ai kiểm soát được thứ hạng của Google.','Tắt quảng cáo ngay khi bắt đầu SEO, để hụt đơn trong nhiều tháng chờ.'],
  q:[
  { type:'mcq', stem:'Đoán trước: trả thêm tiền cho Google có giúp trang lên cao hơn trong kết quả tự nhiên không?',
    options:[{k:'a',t:'Có, tài khoản quảng cáo chi nhiều được Google ưu tiên ở phần tự nhiên'},{k:'b',t:'Không, Google nói không nhận tiền để xếp hạng tự nhiên cao hơn'},
             {k:'c',t:'Có, nếu mua thêm gói xác minh doanh nghiệp có trả phí của Google'},{k:'d',t:'Không trực tiếp, nhưng chi quảng cáo trên 10 triệu/tháng thì được cộng điểm'}],
    answer:'b', why:{a:'Quảng cáo và kết quả tự nhiên là hai hệ thống riêng; chi quảng cáo không mua được chỗ ở phần tự nhiên.',
      b:'Đúng. Trang "How Search works" của Google ghi rõ Google không nhận tiền để thu thập thường hơn hay xếp hạng cao hơn.',
      c:'Không có gói trả phí nào như vậy; xác minh hồ sơ doanh nghiệp là miễn phí và không mua được thứ hạng.',
      d:'Không có ngưỡng chi tiêu nào được "cộng điểm" xếp hạng tự nhiên.'} },
  { type:'mcq', stem:'Agency chào "cam kết top 1 trong 2 tuần, 15 triệu". Bạn chọn cách trả lời nào?',
    options:[{k:'a',t:'Đồng ý nếu agency ký cam kết hoàn tiền khi không lên top đúng hạn'},{k:'b',t:'Đồng ý nhưng chia đợt: trả 50% trước, 50% khi thấy trang lên top'},
             {k:'c',t:'Từ chối, hỏi họ sẽ làm gì cụ thể và đo bằng nhấp, đơn thay vì hứa hạng'},{k:'d',t:'Từ chối SEO, dồn 15 triệu vào quảng cáo vì quảng cáo có số liệu ngay lập tức'}],
    answer:'c', why:{a:'Hoàn tiền không làm lời hứa thành đúng; cách lên top nhanh thường là mua liên kết, rủi ro bị hạ hạng vẫn để lại cho bạn.',
      b:'Chia đợt vẫn là trả tiền cho một lời hứa không ai bảo đảm được, và "thấy lên top" có thể chỉ là trên máy của họ.',
      c:'Đúng. Hỏi việc cụ thể và đo bằng kết quả kinh doanh lộ ra ngay agency làm thật hay bán lời hứa.',
      d:'Bỏ SEO vì một agency xấu là bỏ luôn một kênh tích luỹ; vấn đề nằm ở lời hứa, không ở kênh.'} },
  { type:'calc', stem:'Tiệm có 2.500 lượt nhấp quảng cáo mỗi tháng, giá mỗi nhấp trung bình 3.200đ. Chi phí quảng cáo mỗi tháng là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:8, tol:0.01, wrong:[[0.8,'SAI_TINH_TOAN'],[80,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Chi phí = số nhấp × giá mỗi nhấp.','2.500 × 3.200đ = 8.000.000đ = <b>8 triệu đồng</b> — khoản phải trả lại mỗi tháng để giữ cùng lượng nhấp.'] },
  { type:'mcq', stem:'Vì sao SEO hay được gọi là kênh "tích luỹ"?',
    options:[{k:'a',t:'Trang đã được hiển thị tốt vẫn có thể mang nhấp mà không trả tiền cho từng lượt'},{k:'b',t:'Vì Google cộng điểm cho mỗi tháng trang tồn tại, nên trang càng cũ càng lên cao'},
             {k:'c',t:'Vì chi phí SEO giảm dần về 0 sau năm đầu, không phải làm gì thêm nữa'},{k:'d',t:'Vì từ khoá đã lên top thì giữ nguyên vị trí đó trong nhiều năm liền'}],
    answer:'a', why:{a:'Đúng. Nội dung đã làm vẫn tiếp tục được tìm thấy; quảng cáo thì mỗi nhấp là một lần trả tiền.',
      b:'Tuổi trang không phải điểm cộng tự động; trang cũ mà không hữu ích vẫn có thể bị vượt.',
      c:'Vẫn cần cập nhật nội dung, sửa lỗi kỹ thuật, theo dõi số liệu; chi phí giảm chứ không về 0.',
      d:'Thứ hạng thay đổi theo đối thủ, theo nội dung mới và theo hệ thống của Google.'} },
  { type:'mcq', stem:'Sếp nói: "Làm SEO rồi thì tắt quảng cáo cho đỡ tốn." Điểm yếu của lập luận này là gì?',
    options:[{k:'a',t:'Không yếu, hai kênh nhắm cùng người tìm nên chạy song song là lãng phí tiền'},{k:'b',t:'Yếu vì chạy quảng cáo giúp Google xếp hạng tự nhiên cao hơn'},
             {k:'c',t:'Yếu vì SEO cần ít nhất 12 tháng mới có lượt nhấp đầu tiên, tắt bây giờ là quá sớm'},{k:'d',t:'Trang mới có thể mất vài tuần đến vài tháng mới có nhấp; cần đơn trong lúc chờ'}],
    answer:'d', why:{a:'Hai kênh có thể trùng một phần, nhưng ở giai đoạn đầu SEO chưa thay được lượng đơn từ quảng cáo.',
      b:'Quảng cáo không ảnh hưởng thứ hạng tự nhiên — Google nói không nhận tiền để xếp hạng.',
      c:'Không có mốc 12 tháng cố định; Google nói có thể vài giờ đến vài tháng tuỳ trường hợp.',
      d:'Đúng. Khoảng trống giữa lúc tắt quảng cáo và lúc SEO có nhấp đều là doanh thu bị mất.'} },
  { type:'mcq', stem:'Trên trang kết quả Google, cách phân biệt kết quả tự nhiên với quảng cáo là gì?',
    options:[{k:'a',t:'Kết quả tự nhiên nằm trên cùng, còn quảng cáo được xếp xuống cuối trang'},{k:'b',t:'Quảng cáo có nhãn "Được tài trợ"; phần không có nhãn đó là kết quả tự nhiên'},
             {k:'c',t:'Kết quả tự nhiên có ảnh đi kèm, còn quảng cáo chỉ có chữ và đường link'},{k:'d',t:'Quảng cáo chỉ hiện trên điện thoại, còn máy tính thì chỉ có kết quả tự nhiên thôi'}],
    answer:'b', why:{a:'Quảng cáo thường nằm trên cùng hoặc cuối; vị trí không phải cách phân biệt.',
      b:'Đúng. Nhãn "Được tài trợ" (Sponsored) là dấu hiệu chính thức của quảng cáo.',
      c:'Cả hai đều có thể có ảnh; ảnh không phân biệt được.',
      d:'Quảng cáo tìm kiếm hiện trên cả điện thoại và máy tính.'} },
  { type:'mcq', stem:'Hai lựa chọn cho 6 tháng: (A) 8 triệu/tháng quảng cáo; (B) 5 triệu quảng cáo + 3 triệu nội dung. Nhận định nào công bằng nhất?',
    options:[{k:'a',t:'B tốt hơn ngay từ tháng đầu vì nội dung không tốn tiền cho mỗi lượt nhấp nào'},{k:'b',t:'A tốt hơn vì SEO không đo được nên không ai biết 3 triệu mỗi tháng đã đi đâu'},
             {k:'c',t:'B có thể ít đơn hơn ở tháng đầu, đổi lại có tài sản nội dung nếu được hiển thị'},{k:'d',t:'Hai phương án như nhau vì tổng tiền chi mỗi tháng đều là 8 triệu'}],
    answer:'c', why:{a:'Tháng đầu B bớt 3 triệu quảng cáo mà nội dung chưa có nhấp — thường là ít đơn hơn.',
      b:'SEO đo được bằng Search Console và GA4 (bài 7); khó đo không phải lý do loại.',
      c:'Đúng. Đây là đánh đổi thật: hy sinh một phần đơn ngắn hạn để có nguồn nhấp không trả tiền theo lượt — và không có gì bảo đảm.',
      d:'Cùng tổng chi nhưng khác thời điểm ra kết quả và khác thứ còn lại khi ngừng chi.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:kn11-02', skill:'channel', read:'6 phút', t:'Người gõ "máy lọc nước loại nào tốt" có đang muốn mua ngay không?',
  situation:'Một cửa hàng máy lọc nước ở Đà Nẵng có bài blog "Nước máy có cần lọc không?" nhận 3.000 nhấp mỗi tháng nhưng chỉ ra 15 đơn. Trang "So sánh 3 máy lọc RO cho gia đình 4 người, có giá" chỉ 1.200 nhấp nhưng ra 18 đơn. Chủ cửa hàng định xoá bài blog vì "nhiều người vào mà không mua". (số minh hoạ)',
  concept:{ name:'Ý định tìm kiếm (search intent)',
    body:'Cùng một chủ đề, mỗi truy vấn mang một ý định. Một cách chia phổ biến (Broder, 2002, sau được giới làm nghề thêm nhóm so sánh): <b>thông tin</b> — muốn hiểu ("nước máy có cần lọc không"); <b>so sánh, cân nhắc</b> — đã định mua, chưa chọn được ("RO hay nano"); <b>giao dịch</b> — muốn mua, đặt ("mua máy lọc nước trả góp Đà Nẵng"); <b>điều hướng</b> — muốn tới một trang cụ thể ("tên cửa hàng + bảo hành"). Đây là khung tham khảo của người làm nghề, không phải bảng Google công bố. Cách dùng: gõ truy vấn lên Google, xem trang nào đang hiện để đoán ý định, rồi làm trang khớp ý định đó.' },
  example:'Bài "Nước máy có cần lọc không?" phục vụ ý định thông tin: người đọc mới bắt đầu lo, chưa so máy. 15 đơn trên 3.000 nhấp (0,5%) là hợp lý cho bước này. Trang so sánh khớp ý định cân nhắc: 18 đơn trên 1.200 nhấp (1,5%). Thay vì xoá, cửa hàng thêm cuối bài blog đoạn "Nếu nhà bạn cần lọc, đây là 3 máy phù hợp" dẫn sang trang so sánh, và làm thêm trang giao dịch riêng cho "lắp máy lọc nước tận nhà Đà Nẵng".',
  takeaway:'Đoán ý định từ trang kết quả, rồi làm trang trả lời đúng ý định đó — đừng ép một trang làm mọi việc.',
  apply:'Xếp 6 truy vấn vào 4 nhóm ý định: "máy lọc nước RO là gì", "RO hay nano tốt hơn", "mua máy lọc nước trả góp Đà Nẵng", "[tên cửa hàng] địa chỉ", "giá máy lọc nước 10 lõi", "lõi lọc bao lâu thay một lần". Rồi chọn loại trang cho mỗi nhóm. Đạt khi: (1) mỗi truy vấn có một nhóm và lý do một câu, (2) loại trang khớp nhóm: bài hướng dẫn, trang so sánh, trang sản phẩm hoặc trang liên hệ.',
  mistakes:['Chấm bài thông tin bằng số đơn trực tiếp rồi xoá nó.','Nhồi nút "Mua ngay" và bảng giá vào đầu bài hướng dẫn, khiến người đang tìm hiểu bỏ đi.'],
  q:[
  { type:'mcq', stem:'Đoán trước: người gõ "máy lọc nước loại nào tốt" thuộc nhóm ý định nào?',
    options:[{k:'a',t:'Điều hướng, vì họ đang tìm tới trang của một hãng máy lọc cụ thể'},{k:'b',t:'Giao dịch, vì có chữ "máy lọc nước" là tên một sản phẩm cụ thể'},
             {k:'c',t:'Thông tin thuần, vì họ chưa hề nghĩ tới chuyện mua máy lọc nước'},{k:'d',t:'So sánh, cân nhắc: họ đã định mua nhưng chưa chọn được loại'}],
    answer:'d', why:{a:'Không nêu tên hãng hay trang nào; họ chưa biết muốn tới đâu.',
      b:'Có tên sản phẩm chưa đủ thành giao dịch; "loại nào tốt" là câu hỏi đang chọn.',
      c:'Hỏi "loại nào" cho thấy họ đã nghĩ tới mua, chỉ chưa chọn.',
      d:'Đúng. Đây là bước cân nhắc: trang so sánh có tiêu chí và giá trả lời họ tốt nhất.'} },
  { type:'mcq', stem:'Chủ cửa hàng muốn xoá bài blog 3.000 nhấp chỉ ra 15 đơn. Bạn đề xuất gì?',
    options:[{k:'a',t:'Giữ bài, thêm đoạn dẫn sang trang so sánh cho người đã sẵn sàng cân nhắc'},{k:'b',t:'Xoá bài, dồn sức vào trang so sánh vì trang đó ra nhiều đơn hơn hẳn mỗi tháng'},
             {k:'c',t:'Sửa bài thành trang bán: thêm giá và nút mua ở đầu và giữa bài viết'},{k:'d',t:'Giữ nguyên bài, không thêm gì vì bài thông tin thì không cần ra đơn'}],
    answer:'a', why:{a:'Đúng. Bài thông tin giữ vai trò đón người mới bắt đầu; một đường dẫn rõ giúp người sẵn sàng đi tiếp.',
      b:'Xoá bài là cắt mất cửa đón người ở bước sớm — một phần trong số họ về sau thành người so sánh.',
      c:'Biến bài hướng dẫn thành trang bán làm lệch ý định; người đang tìm hiểu dễ bỏ đi.',
      d:'Không cần ra đơn trực tiếp, nhưng bỏ trống đường đi tiếp là phí 3.000 người đã vào.'} },
  { type:'calc', stem:'Trang so sánh có 1.200 nhấp và 18 đơn trong tháng. Tỉ lệ ra đơn trên nhấp của trang này là bao nhiêu phần trăm?',
    unit:'%', ans:1.5, tol:0.01, wrong:[[0.6,'SAI_MAU_SO'],[66.7,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ ra đơn = đơn ÷ nhấp của chính trang đó.','18 ÷ 1.200 = <b>1,5%</b>. Lấy 18 ÷ 3.000 (nhấp của bài blog) ra 0,6% là nhầm mẫu số.'] },
  { type:'mcq', stem:'Cách nhanh nhất để đoán ý định của một truy vấn trước khi viết trang là gì?',
    options:[{k:'a',t:'Đoán theo độ dài: truy vấn dài là giao dịch, truy vấn ngắn là thông tin'},{k:'b',t:'Hỏi nhân viên bán hàng xem khách hay hỏi gì nhất ở quầy tuần trước'},
             {k:'c',t:'Gõ truy vấn lên Google, xem trang đang hiện là hướng dẫn, so sánh hay trang bán'},{k:'d',t:'Xem cột "Cạnh tranh" của Keyword Planner: mức cao là giao dịch, mức thấp là thông tin'}],
    answer:'c', why:{a:'Độ dài không quyết định ý định; "lõi lọc bao lâu thay một lần" dài mà vẫn là thông tin.',
      b:'Có ích để tìm chủ đề, nhưng không cho biết Google đang hiểu truy vấn đó theo ý định nào.',
      c:'Đúng. Loại trang Google đang chọn hiển thị là gợi ý rõ nhất về ý định người tìm.',
      d:'Cột đó đo số nhà quảng cáo đấu giá từ khoá, không đo ý định.'} },
  { type:'mcq', stem:'Truy vấn "[tên cửa hàng] giờ mở cửa" thuộc nhóm nào, và trang nào nên trả lời?',
    options:[{k:'a',t:'Thông tin; viết một bài blog dài về lịch sử hình thành của cửa hàng mình'},{k:'b',t:'Điều hướng; trang liên hệ và hồ sơ Google Business có giờ mở đúng'},
             {k:'c',t:'Giao dịch; trang sản phẩm bán chạy nhất để tranh thủ chốt đơn'},{k:'d',t:'So sánh; trang so sánh cửa hàng mình với các cửa hàng khác'}],
    answer:'b', why:{a:'Người tìm cần một con số giờ mở cửa, không cần đọc lịch sử.',
      b:'Đúng. Họ đã biết cửa hàng, chỉ cần tới đúng chỗ có thông tin chính xác.',
      c:'Ép trang bán vào câu hỏi giờ mở cửa làm người tìm phải tìm lại.',
      d:'Họ không so sánh; họ đã chọn cửa hàng của bạn.'} },
  { type:'mcq', stem:'Một shop mỹ phẩm muốn lên cho "cách trị mụn ẩn" bằng trang sản phẩm serum. Rủi ro chính là gì?',
    options:[{k:'a',t:'Trang sản phẩm quá ngắn nên Google không thể lập chỉ mục được'},{k:'b',t:'Từ khoá có nhiều người tìm nên shop nhỏ không được phép nhắm tới'},
             {k:'c',t:'Trang thiếu từ khoá, chỉ cần lặp "trị mụn ẩn" thêm vài lần trong bài là khớp'},{k:'d',t:'Người tìm muốn biết cách trị, nên trang chỉ để bán serum lệch ý định'}],
    answer:'d', why:{a:'Trang ngắn vẫn được lập chỉ mục; vấn đề là nó không trả lời điều người tìm hỏi.',
      b:'Không có quy định cấm nhắm từ khoá nào; chỉ là khó thắng hơn.',
      c:'Lặp từ khoá là nhồi từ khoá, Google coi là spam; và vẫn không trả lời câu hỏi.',
      d:'Đúng. Người tìm cần bài hướng dẫn; serum có thể được nhắc trong bài như một lựa chọn.'} },
  { type:'mcq', stem:'Đồng nghiệp nói: "Bài blog ra đơn 0,5%, thấp gấp 3 lần trang so sánh, vậy bài blog kém." Điểm sai trong lập luận?',
    options:[{k:'a',t:'So hai trang phục vụ hai ý định khác nhau bằng cùng thước đo ra đơn trực tiếp'},{k:'b',t:'Tính sai: 15 ÷ 3.000 thực ra là 5%, không phải 0,5% như đã nói'},
             {k:'c',t:'Không sai, trang nào ra đơn ít hơn thì kém hơn và nên dừng đầu tư'},{k:'d',t:'Sai vì tỉ lệ ra đơn không dùng được cho kênh tự nhiên, chỉ dùng cho quảng cáo trả tiền'}],
    answer:'a', why:{a:'Đúng. Bài thông tin đón người ở bước sớm; đo nó bằng đơn ngay lập tức là đo sai việc.',
      b:'15 ÷ 3.000 = 0,005 = 0,5%; phép tính đúng, lập luận mới sai.',
      c:'Theo cách đó mọi bài hướng dẫn đều bị dừng, và cửa hàng mất nguồn người mới.',
      d:'Tỉ lệ ra đơn dùng được cho mọi kênh; vấn đề là so hai trang khác vai trò.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:kn11-03', skill:'channel', read:'6 phút', t:'Nhắm từ khoá 12.000 lượt tìm hay 900 lượt tìm — chọn cái nào?',
  situation:'Cửa hàng máy lọc nước ở Đà Nẵng có ngân sách viết 4 trang mới trong quý. Danh sách từ khoá: "máy lọc nước" 12.000 lượt tìm/tháng, trang 1 toàn hãng lớn và sàn thương mại điện tử; "máy lọc nước cho chung cư" 900 lượt; "RO hay nano" 600 lượt; "lắp máy lọc nước Đà Nẵng" 300 lượt. Nhân viên muốn dồn hết vào "máy lọc nước" vì "số to nhất". (số minh hoạ)',
  concept:{ name:'Chấm từ khoá bằng ba cột: lượng tìm, ý định, khả năng thắng',
    body:'Đừng chọn từ khoá chỉ theo lượng tìm. Chấm mỗi từ theo ba cột: <b>lượng tìm</b> mỗi tháng (Keyword Planner hoặc Search Console; là ước tính đã làm tròn), <b>khớp ý định</b> (người tìm có gần quyết định mua thứ bạn bán không), <b>khả năng thắng</b> (trang 1 hiện là ai: hãng lớn, sàn, hay trang nhỏ giống bạn). Lưu ý: cột "Cạnh tranh" trong Keyword Planner đo <b>số nhà quảng cáo</b> hiển thị cho từ khoá đó so với các từ khác (Google Ads Help, kiểm 10/2026), không phải độ khó lên top tự nhiên. Sau đó ước <b>nhấp kỳ vọng = lượng tìm × CTR giả định</b> ở vị trí bạn có thể đạt. CTR theo vị trí là giả định của bạn, không phải số Google công bố; có dữ liệu thật thì thay vào.' },
  example:'Giả định (số minh hoạ, không phải benchmark): trang mới khó vượt trang 2 với "máy lọc nước", CTR khoảng 1% → 12.000 × 1% = 120 nhấp, phần lớn là người mới tìm hiểu. Với "máy lọc nước cho chung cư", trang 1 có vài cửa hàng nhỏ; nếu lên khoảng vị trí 3, giả định CTR 10% → 900 × 10% = 90 nhấp, đúng người đang chọn máy. "Lắp máy lọc nước Đà Nẵng": 300 × 15% = 45 nhấp, gần như toàn khách sắp mua. Cửa hàng chọn các từ nhỏ khớp ý định trước.',
  takeaway:'Lượt tìm to chưa chắc mang khách: nhân với khả năng thắng và xét độ khớp ý định trước khi chọn.',
  apply:'Một shop bán và sửa nồi chiên không dầu ở Hà Nội có bảng: "nồi chiên không dầu" 20.000 lượt, trang 1 toàn sàn lớn; "nồi chiên không dầu cho 2 người" 700 lượt, trang 1 có blog nhỏ; "sửa nồi chiên không dầu Hà Nội" 250 lượt. Giả định CTR (minh hoạ): 1% nếu ở trang 2, 10% nếu ở vị trí 3, 15% nếu ở vị trí 1. Tính nhấp kỳ vọng từng từ và chọn 2 từ viết trước. Đạt khi: (1) có ba phép tính nhấp kỳ vọng, (2) lý do chọn nhắc tới ý định, không chỉ số nhấp.',
  mistakes:['Đọc cột "Cạnh tranh" của Keyword Planner như độ khó SEO.','Coi một bảng CTR theo vị trí đọc trên mạng là sự thật cho mọi từ khoá.'],
  q:[
  { type:'mcq', stem:'Đoán trước: với cửa hàng nhỏ mới làm SEO, từ khoá nào nhiều khả năng mang đơn sớm nhất?',
    options:[{k:'a',t:'"máy lọc nước" vì có 12.000 lượt tìm, lớn nhất trong danh sách'},{k:'b',t:'"RO hay nano" vì người hỏi so sánh là người hiểu sản phẩm nhất'},
             {k:'c',t:'"lắp máy lọc nước Đà Nẵng" vì ý định mua rõ và ít đối thủ mạnh'},{k:'d',t:'Bốn từ như nhau, chỉ khác lượt tìm nên mang đơn tương đương'}],
    answer:'c', why:{a:'Lượt tìm lớn nhưng trang 1 toàn hãng lớn và sàn; trang mới khó chen vào, và nhiều người chỉ đang tìm hiểu.',
      b:'Người so sánh gần mua hơn người hỏi thông tin, nhưng chưa rõ bằng người đã tìm "lắp ... Đà Nẵng".',
      c:'Đúng. Ít lượt tìm nhưng gần như toàn người sắp mua, ở đúng khu vực, và đối thủ mạnh ít.',
      d:'Bốn từ khác cả ý định lẫn đối thủ; đơn mang về khác xa nhau.'} },
  { type:'mcq', stem:'Nhân viên muốn dồn cả 4 trang vào "máy lọc nước". Bạn chọn cách nào?',
    options:[{k:'a',t:'Đồng ý, viết 4 bài cùng nhắm "máy lọc nước" để tăng cơ hội lên top'},{k:'b',t:'Chấm 4 từ theo lượng tìm, ý định, khả năng thắng; ưu tiên từ nhỏ khớp ý định'},
             {k:'c',t:'Chọn theo cột "Cạnh tranh" thấp nhất trong Keyword Planner, bỏ qua phần ý định'},{k:'d',t:'Bỏ SEO, chỉ chạy quảng cáo cho "máy lọc nước" vì nhiều người tìm nhất'}],
    answer:'b', why:{a:'Bốn bài cùng một từ khoá dễ tự cạnh tranh nhau, và vẫn phải đấu với hãng lớn.',
      b:'Đúng. Ba cột buộc bạn nhìn cả số, người tìm và đối thủ trước khi tiêu ngân sách.',
      c:'Cột đó đo nhà quảng cáo, không đo độ khó tự nhiên; và bỏ ý định là bỏ phần quan trọng nhất.',
      d:'Từ khoá rộng thường đắt và lẫn nhiều người chưa định mua; chưa chắc là chỗ tiêu tiền tốt.'} },
  { type:'calc', stem:'Từ khoá "máy lọc nước cho chung cư" có 900 lượt tìm/tháng. Giả định (số minh hoạ) trang ở khoảng vị trí 3 có CTR 10%. Nhấp kỳ vọng mỗi tháng là bao nhiêu?',
    unit:'nhấp', ans:90, tol:0.5, wrong:[[9000,'SAI_TINH_TOAN'],[9,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Nhấp kỳ vọng = lượng tìm × CTR giả định.','900 × 10% = <b>90 nhấp</b>/tháng. CTR 10% là giả định minh hoạ; khi trang có dữ liệu, thay bằng CTR thật trong Search Console.'] },
  { type:'mcq', stem:'Cột "Cạnh tranh" (thấp/trung bình/cao) trong Keyword Planner cho biết điều gì?',
    options:[{k:'a',t:'Độ khó để trang của bạn lọt được vào top 10 kết quả tìm kiếm tự nhiên'},{k:'b',t:'Số trang web đã viết bài có chứa đúng cụm từ khoá đó'},
             {k:'c',t:'Mức độ người tìm sẵn sàng mua hàng sau khi tìm kiếm'},{k:'d',t:'Số nhà quảng cáo hiển thị cho từ khoá đó, so với các từ khác'}],
    answer:'d', why:{a:'Đây là hiểu lầm phổ biến nhất; Keyword Planner là công cụ của Google Ads, không đo độ khó SEO.',
      b:'Công cụ không đếm số trang chứa từ khoá.',
      c:'Ý định mua phải đoán từ truy vấn và trang kết quả, không từ cột này.',
      d:'Đúng. Theo Google Ads Help, đó là số nhà quảng cáo hiển thị cho từ khoá, tương đối so với mọi từ khoá.'} },
  { type:'mcq', stem:'Vì sao phải nhân với "khả năng thắng" thay vì chỉ nhìn lượng tìm thô?',
    options:[{k:'a',t:'Nhấp thường dồn vào vị trí đầu; ở trang 2, lượt tìm lớn vẫn có thể ra rất ít nhấp'},{k:'b',t:'Vì Google giới hạn mỗi website chỉ được nhắm 10 từ khoá mỗi năm'},
             {k:'c',t:'Vì từ khoá nhiều lượt tìm bị Google phạt nếu website nhỏ nhắm vào'},{k:'d',t:'Vì khả năng thắng đo bằng số nhà quảng cáo nên phản ánh đúng độ khó lên top tự nhiên'}],
    answer:'a', why:{a:'Đúng. Lượng tìm chỉ là số người có thể thấy; bạn ở đâu trên trang mới quyết định bao nhiêu người bấm.',
      b:'Không có giới hạn số từ khoá nào như vậy.',
      c:'Google không phạt việc nhắm từ khoá lớn; chỉ là khó thắng.',
      d:'Số nhà quảng cáo không đo độ khó tự nhiên; khả năng thắng nhìn từ trang 1 hiện tại.'} },
  { type:'mcq', stem:'Đồng nghiệp gửi bảng: "Vị trí 1 có CTR 30%, nên lên top là có 3.600 nhấp từ 12.000 lượt tìm." Lỗi lớn nhất là gì?',
    options:[{k:'a',t:'Tính sai: 12.000 × 30% chỉ là 360 nhấp, không phải 3.600'},{k:'b',t:'Không lỗi, 30% là tỉ lệ Google công bố cho vị trí số 1'},
             {k:'c',t:'Coi CTR đọc ở đâu đó là đúng cho từ này, và mặc định lên được vị trí 1'},{k:'d',t:'Lẽ ra phải chia lượt tìm cho số nhà quảng cáo thay vì nhân với CTR vị trí 1'}],
    answer:'c', why:{a:'12.000 × 30% = 3.600; phép nhân đúng, giả định mới sai.',
      b:'Google không công bố bảng CTR theo vị trí; CTR thật tuỳ truy vấn, quảng cáo phía trên và giao diện kết quả.',
      c:'Đúng. Hai giả định chồng lên nhau: CTR mượn từ nơi khác, và một trang mới lên ngay vị trí 1 trước hãng lớn.',
      d:'Số nhà quảng cáo không có chỗ trong công thức nhấp kỳ vọng.'} },
  { type:'mcq', stem:'Sau 3 tháng, Search Console cho thấy từ khoá đó có 900 lần hiển thị và CTR 4%. Bạn làm gì với giả định CTR 10% ban đầu?',
    options:[{k:'a',t:'Giữ 10% vì đó là con số cả nhóm đã thống nhất trong kế hoạch quý này'},{k:'b',t:'Bỏ hẳn từ khoá vì CTR chưa bằng một nửa con số kế hoạch'},
             {k:'c',t:'Nâng giả định lên 15% để bù lại cho những tháng đầu thấp'},{k:'d',t:'Thay bằng số thật 4%, xem vị trí và tiêu đề để biết vì sao thấp'}],
    answer:'d', why:{a:'Giữ giả định khi đã có số thật là tự lừa mình.',
      b:'CTR thấp có thể do vị trí hoặc tiêu đề, sửa được; bỏ ngay là vội.',
      c:'Đẩy giả định lên không làm khách bấm nhiều hơn.',
      d:'Đúng. Giả định chỉ dùng khi chưa có dữ liệu; có rồi thì thay và tìm nguyên nhân.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:kn11-04', skill:'channel', read:'6 phút', t:'Viết 120 bài na ná nhau hay 10 bài thật sự giúp người đọc?',
  situation:'Một shop mỹ phẩm online thuê viết 120 bài blog trong 6 tháng, mỗi bài khoảng 600 chữ, 150.000đ/bài, chủ đề lấy từ danh sách từ khoá, nội dung na ná nhau. Search Console cho thấy chỉ 18 bài có lượt nhấp. Một bài do dược sĩ của shop viết về "dùng retinol lần đầu", có ảnh da thật và lịch dùng từng tuần, mang về gần một nửa số nhấp. (số minh hoạ)',
  concept:{ name:'Nội dung hữu ích, đặt người đọc lên trước (people-first) và E-E-A-T',
    body:'Google khuyên tạo nội dung <b>chủ yếu để giúp người đọc</b>, không phải để kéo lượt truy cập từ công cụ tìm kiếm. Tài liệu "Creating helpful, reliable, people-first content" gợi ý tự hỏi: ai viết (người đọc có thấy rõ không), viết thế nào, và vì sao viết. E-E-A-T gồm kinh nghiệm (Experience), chuyên môn (Expertise), uy tín (Authoritativeness), đáng tin (Trust); đáng tin là quan trọng nhất. Nói cho chính xác: Google viết rằng E-E-A-T <b>tự nó không phải một yếu tố xếp hạng cụ thể</b>. Đó là khung mà người đánh giá chất lượng dùng; người đánh giá không quyết định thứ hạng. Hệ thống xếp hạng dùng nhiều tín hiệu để nhận ra nội dung có những phẩm chất đó. (Google Search Central, kiểm 10/2026)' },
  example:'Bài retinol có kinh nghiệm thật (ảnh da sau 4 tuần), chuyên môn (dược sĩ ký tên, ghi chức danh) và đáng tin (nói rõ ai không nên dùng, khi nào cần gặp bác sĩ da liễu). 120 bài thuê viết trả lời chung chung, đọc xong vẫn phải tìm tiếp. Shop dừng viết mới, gộp các bài trùng chủ đề, viết lại 10 bài từ câu hỏi thật của khách, ghi tên người viết. E-E-A-T không phải thẻ kỹ thuật để "thêm vào"; nó là chất lượng người đọc nhìn thấy được.',
  takeaway:'Viết để người đọc không phải tìm tiếp; E-E-A-T là khung chất lượng, không phải nút bật thứ hạng.',
  apply:'Cho dàn ý bài "Kem chống nắng cho da dầu": 5 đoạn định nghĩa chung, lặp "kem chống nắng da dầu" 15 lần, không ghi tác giả, không thử thật. Viết lại dàn ý 5 ý. Đạt khi: (1) có ít nhất một chi tiết kinh nghiệm thật hoặc một phép thử, (2) ghi ai viết và vì sao đáng tin, (3) trả lời câu hỏi kế tiếp người đọc sẽ hỏi.',
  mistakes:['Nói "tối ưu E-E-A-T" như cài một thẻ hay plugin để tăng thứ hạng.','Đo năng suất nội dung bằng số bài thay vì số bài thật sự được đọc và dùng.'],
  q:[
  { type:'mcq', stem:'Đoán trước: theo tài liệu của Google, E-E-A-T là gì?',
    options:[{k:'a',t:'Một khung đánh giá chất lượng; tự nó không phải một yếu tố xếp hạng cụ thể'},{k:'b',t:'Một điểm số Google chấm cho mỗi website và hiển thị trong Search Console'},
             {k:'c',t:'Một yếu tố xếp hạng trực tiếp do người đánh giá chất lượng chấm cho từng trang'},{k:'d',t:'Một chứng nhận trả phí mà website có thể đăng ký để được ưu tiên hiển thị'}],
    answer:'a', why:{a:'Đúng. Google viết E-E-A-T tự nó không phải yếu tố xếp hạng cụ thể; hệ thống dùng nhiều tín hiệu để nhận ra nội dung có các phẩm chất đó.',
      b:'Không có điểm E-E-A-T nào trong Search Console.',
      c:'Google nói người đánh giá không kiểm soát thứ hạng và dữ liệu của họ không dùng trực tiếp trong thuật toán.',
      d:'Không có chứng nhận trả phí nào; Google không nhận tiền để xếp hạng.'} },
  { type:'mcq', stem:'Shop còn ngân sách cho 20 bài nữa. Bạn chọn cách dùng nào?',
    options:[{k:'a',t:'Thuê thêm 20 bài như cũ vì có 18 bài ra nhấp, càng nhiều bài càng nhiều cơ hội'},{k:'b',t:'Chép lại 20 bài nhiều nhấp nhất của đối thủ rồi đổi lời cho khác đi một chút'},
             {k:'c',t:'Viết 20 bài mới nhắm 20 từ khoá chưa có trong danh sách để phủ rộng hơn'},{k:'d',t:'Gộp bài trùng, viết lại ít bài hơn có dược sĩ ký tên, trả lời câu hỏi thật'}],
    answer:'d', why:{a:'102 bài không có nhấp cho thấy làm thêm cùng kiểu chủ yếu là thêm bài không ai đọc.',
      b:'Chép và đổi lời không thêm giá trị gì; Google coi nội dung sao chép hàng loạt là dấu hiệu chất lượng thấp.',
      c:'Phủ rộng bằng bài mỏng lặp lại đúng lỗi cũ ở chủ đề mới.',
      d:'Đúng. Đi theo mẫu bài đã chạy: kinh nghiệm thật, người viết rõ, trả lời đúng câu khách hỏi.'} },
  { type:'calc', stem:'Shop có 120 bài, 18 bài có lượt nhấp. Bao nhiêu phần trăm số bài không mang về lượt nhấp nào?',
    unit:'%', ans:85, tol:0.1, wrong:[[15,'NHAM_TI_LE_ROI'],[102,'SAI_TINH_TOAN']], errors:['NHAM_TI_LE_ROI','SAI_TINH_TOAN'],
    steps:['Số bài không có nhấp = 120 − 18 = 102.','102 ÷ 120 = <b>85%</b>. 15% là tỉ lệ bài CÓ nhấp; 102 là số bài, chưa phải phần trăm.'] },
  { type:'mcq', stem:'Ba câu hỏi Google gợi ý để tự kiểm một nội dung là gì?',
    options:[{k:'a',t:'Bao nhiêu chữ, bao nhiêu từ khoá, bao nhiêu liên kết'},{k:'b',t:'Ai viết, viết thế nào, và vì sao viết'},
             {k:'c',t:'Khi nào đăng, đăng ở đâu, đăng bao nhiêu lần một tuần'},{k:'d',t:'Đối thủ viết gì, viết dài bao nhiêu, đang xếp hạng mấy'}],
    answer:'b', why:{a:'Google không đặt độ dài chuẩn; đếm chữ và từ khoá là cách viết cho máy.',
      b:'Đúng. "Who, How, Why" trong tài liệu people-first content của Google.',
      c:'Lịch đăng là chuyện vận hành, không phải tiêu chí chất lượng nội dung.',
      d:'Nhìn đối thủ có ích, nhưng không phải bộ câu hỏi Google gợi ý.'} },
  { type:'mcq', stem:'Trong bốn chữ của E-E-A-T, Google nói chữ nào quan trọng nhất?',
    options:[{k:'a',t:'Kinh nghiệm (Experience), vì đó là chữ được thêm vào sau cùng'},{k:'b',t:'Chuyên môn (Expertise), vì người viết nào cũng phải có bằng cấp'},
             {k:'c',t:'Đáng tin (Trust); các chữ còn lại góp phần tạo ra nó'},{k:'d',t:'Uy tín (Authoritativeness), vì chỉ đo bằng số liên kết trỏ về'}],
    answer:'c', why:{a:'Kinh nghiệm được thêm sau, nhưng mới thêm không làm nó quan trọng nhất.',
      b:'Nhiều chủ đề chỉ cần kinh nghiệm sống, không cần bằng cấp.',
      c:'Đúng. Google viết "trust is most important"; ba chữ kia hỗ trợ cho sự đáng tin.',
      d:'Uy tín không chỉ là đếm liên kết; và nó không phải chữ quan trọng nhất.'} },
  { type:'mcq', stem:'Agency báo: "Đã tối ưu E-E-A-T: gắn thẻ tác giả vào 120 bài, nên thứ hạng sẽ lên." Điểm yếu của báo cáo?',
    options:[{k:'a',t:'Gắn thẻ không làm bài hữu ích hơn; E-E-A-T không phải nút bật thứ hạng'},{k:'b',t:'Thẻ tác giả bị Google cấm nên cả 120 bài sẽ bị phạt nặng'},
             {k:'c',t:'Không có điểm yếu, có tên tác giả trên mỗi bài là đủ để Google tin nội dung'},{k:'d',t:'E-E-A-T chỉ áp dụng cho trang y tế, không áp dụng cho mỹ phẩm'}],
    answer:'a', why:{a:'Đúng. Ghi tác giả là tốt cho người đọc, nhưng 120 bài chung chung vẫn chung chung; không có gì "bật" thứ hạng.',
      b:'Ghi tác giả không bị cấm; Google còn khuyến khích cho người đọc thấy ai viết.',
      c:'Tên tác giả là một phần; nội dung vẫn phải có kinh nghiệm thật và đáng tin.',
      d:'Khung này dùng cho mọi chủ đề; với chủ đề sức khoẻ, tiền bạc thì càng được xét kỹ.'} },
  { type:'mcq', stem:'Nhận định nào về nội dung "viết cho công cụ tìm kiếm trước, người đọc sau" khớp với hướng dẫn của Google?',
    options:[{k:'a',t:'Được khuyến khích nếu bài đủ dài trên 2.000 chữ và nhiều tiêu đề phụ'},{k:'b',t:'Là dấu hiệu cần tránh; nội dung nên làm chủ yếu để giúp người đọc'},
             {k:'c',t:'Vô hại vì Google chỉ đọc từ khoá và bỏ qua phần nội dung còn lại'},{k:'d',t:'Là cách duy nhất để một trang mới có lượt nhấp trong năm đầu tiên'}],
    answer:'b', why:{a:'Google nói không có độ dài chữ ưu tiên; bài dài viết cho máy vẫn là viết cho máy.',
      b:'Đúng. Google khuyên tránh nội dung "search engine-first" và đưa ra danh sách dấu hiệu để tự kiểm.',
      c:'Hệ thống của Google đọc và đánh giá nội dung, không chỉ đếm từ khoá.',
      d:'Bài retinol của dược sĩ cho thấy nội dung viết cho người vẫn mang nhấp.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:kn11-05', skill:'channel', read:'6 phút', t:'Trang đẹp trên máy tính nhưng khách điện thoại bỏ đi — kiểm gì trong một buổi?',
  situation:'Một nhà hàng lẩu ở Cầu Giấy, Hà Nội có website. Trang thực đơn có tiêu đề trang là "Trang chủ", không có mô tả, đường dẫn dạng /page?id=4821, ảnh menu nặng 8 MB tải mãi không xong trên điện thoại. Search Console cho thấy tháng trước có 1.400 nhấp tự nhiên, trong đó 1.120 nhấp từ điện thoại. Chủ quán hỏi nên sửa gì trước. (số minh hoạ)',
  concept:{ name:'Kỹ thuật cơ bản: checklist một trang',
    body:'Phần kỹ thuật giúp Google tìm, hiểu và hiển thị đúng trang của bạn. Người mới kiểm sáu thứ. <b>Tiêu đề trang</b> (thẻ title): riêng cho từng trang, rõ, mô tả đúng nội dung — Google dùng nó cùng các tiêu đề khác để tạo tiêu đề kết quả. <b>Mô tả</b> (meta description): ngắn, riêng, đúng — đôi khi Google lấy làm đoạn trích. <b>URL</b> có chữ có nghĩa thay cho mã số. <b>Tốc độ</b> tải, nhất là ảnh. <b>Hiển thị trên điện thoại</b>. <b>Sơ đồ trang (sitemap)</b>: tuỳ chọn, hữu ích khi site mới hoặc lớn. Google Search không dùng thẻ meta keywords. (Google SEO Starter Guide, kiểm 10/2026)' },
  example:'Quán sửa trong một buổi: tiêu đề trang thành "Thực đơn lẩu Thái, lẩu nấm – [tên quán], Cầu Giấy"; mô tả một câu nêu giá từ 189.000đ/người và giờ mở cửa; URL thành /thuc-don-lau; ảnh menu nén xuống dưới 300 KB và thêm bản chữ để đọc trên điện thoại; gửi sitemap trong Search Console. 1.120 trên 1.400 nhấp đến từ điện thoại, nên quán kiểm mọi thứ trên điện thoại trước. Quán không điền meta keywords vì Google không dùng thẻ này.',
  takeaway:'Tiêu đề, mô tả, URL, tốc độ, điện thoại, sitemap: kiểm đủ sáu thứ trước khi mua công cụ đắt tiền.',
  apply:'Cho trang bán bánh mì que giao tận nơi ở Hải Phòng, 25.000đ/hộp: tiêu đề "Sản phẩm", mô tả trống, URL /p?id=93, ảnh 5 MB, chữ nhỏ trên điện thoại. Viết lại tiêu đề, mô tả, URL và ghi 2 việc sửa kỹ thuật. Đạt khi: (1) tiêu đề nêu sản phẩm và nơi bán, (2) mô tả có một lý do để bấm, (3) URL có chữ có nghĩa.',
  mistakes:['Đặt cùng một tiêu đề "Trang chủ" cho mọi trang.','Mất công điền thẻ meta keywords, thứ Google Search không dùng.'],
  q:[
  { type:'mcq', stem:'Đoán trước: Google Search có dùng thẻ meta keywords để xếp hạng không?',
    options:[{k:'a',t:'Có, đó là thẻ quan trọng nhất để Google biết trang nói về gì'},{k:'b',t:'Có, nhưng Google chỉ tính 10 từ khoá đầu tiên ghi trong thẻ'},
             {k:'c',t:'Không, Google Search không dùng thẻ meta keywords'},{k:'d',t:'Chỉ dùng cho trang tiếng Việt vì tiếng Việt khó phân tích hơn'}],
    answer:'c', why:{a:'Google hiểu trang từ nội dung, tiêu đề và nhiều tín hiệu khác, không từ thẻ này.',
      b:'Không có quy tắc 10 từ nào; Google không dùng thẻ này.',
      c:'Đúng. SEO Starter Guide ghi rõ Google Search không dùng thẻ meta keywords.',
      d:'Không có ngoại lệ theo ngôn ngữ.'} },
  { type:'mcq', stem:'Chủ quán chỉ có một buổi sáng. Bạn chọn sửa gì trước?',
    options:[{k:'a',t:'Mua công cụ kiểm tra SEO trả phí và chạy một báo cáo đủ 200 lỗi cho cả site'},{k:'b',t:'Tiêu đề, mô tả và ảnh nặng của trang thực đơn, kiểm trên điện thoại'},
             {k:'c',t:'Viết 10 bài blog mới về lịch sử món lẩu để có thêm nội dung'},{k:'d',t:'Thêm thẻ meta keywords chứa 30 từ khoá về lẩu cho tất cả trang'}],
    answer:'b', why:{a:'Báo cáo 200 lỗi không cho biết sửa gì trước; lỗi lớn nhất đã lộ rõ ở trang thực đơn.',
      b:'Đúng. Trang được tìm nhiều nhất, lỗi rõ nhất, và 80% khách đến từ điện thoại.',
      c:'Bài mới không cứu được trang thực đơn đang tải không nổi.',
      d:'Google không dùng thẻ này; một buổi sáng bị phí.'} },
  { type:'calc', stem:'Tháng trước có 1.400 nhấp tự nhiên, trong đó 1.120 nhấp từ điện thoại. Điện thoại chiếm bao nhiêu phần trăm số nhấp?',
    unit:'%', ans:80, tol:0.1, wrong:[[20,'NHAM_TI_LE_ROI'],[125,'SAI_MAU_SO']], errors:['NHAM_TI_LE_ROI','SAI_MAU_SO'],
    steps:['Tỉ lệ = nhấp từ điện thoại ÷ tổng nhấp.','1.120 ÷ 1.400 = <b>80%</b>. 20% là phần máy tính; 1.400 ÷ 1.120 = 125% là chia ngược.'] },
  { type:'mcq', stem:'Mô tả (meta description) có vai trò gì theo Google?',
    options:[{k:'a',t:'Đôi khi được dùng làm đoạn trích dưới tiêu đề, nên viết ngắn, riêng, đúng'},{k:'b',t:'Là yếu tố xếp hạng chính, càng chứa nhiều từ khoá thì trang càng được lên cao'},
             {k:'c',t:'Bắt buộc phải có; trang thiếu mô tả sẽ không được Google lập chỉ mục'},{k:'d',t:'Chỉ hiện trên máy tính, còn điện thoại bị ẩn đi để tiết kiệm chỗ'}],
    answer:'a', why:{a:'Đúng. Đoạn trích thường lấy từ nội dung trang; đôi khi lấy từ mô tả — nên mô tả tốt vẫn đáng viết.',
      b:'Nhồi từ khoá vào mô tả không giúp xếp hạng và làm đoạn trích khó đọc.',
      c:'Thiếu mô tả vẫn được lập chỉ mục; Google tự lấy đoạn trích từ nội dung.',
      d:'Đoạn trích hiện trên cả điện thoại và máy tính.'} },
  { type:'mcq', stem:'Sitemap (sơ đồ trang) nên được hiểu thế nào?',
    options:[{k:'a',t:'Bắt buộc; thiếu sitemap thì Google không tìm được trang nào của site'},{k:'b',t:'Là cách trả phí để Google thu thập trang nhanh hơn đối thủ cùng ngành'},
             {k:'c',t:'Thay được hẳn liên kết nội bộ giữa các trang trong cùng một website'},{k:'d',t:'Danh sách URL muốn Google biết; tuỳ chọn, có ích với site mới hoặc lớn'}],
    answer:'d', why:{a:'Google vẫn tìm trang qua liên kết; sitemap là tuỳ chọn.',
      b:'Sitemap miễn phí, và Google không nhận tiền để thu thập thường hơn.',
      c:'Liên kết nội bộ vẫn cần cho người đọc và để Google hiểu cấu trúc site.',
      d:'Đúng. Google gọi sitemap là cách báo URL bạn quan tâm; hữu ích nhưng không bắt buộc.'} },
  { type:'mcq', stem:'Tiêu đề trang nào tốt nhất cho trang thực đơn của quán?',
    options:[{k:'a',t:'Trang chủ – Chào mừng quý khách đến với website của chúng tôi'},{k:'b',t:'Lẩu ngon lẩu rẻ lẩu Hà Nội lẩu Thái lẩu nấm lẩu bò lẩu gà'},
             {k:'c',t:'Thực đơn | Trang 4821 | Danh mục sản phẩm | Website'},{k:'d',t:'Thực đơn lẩu Thái, lẩu nấm – [tên quán], Cầu Giấy'}],
    answer:'d', why:{a:'Không nói trang có gì; người tìm không biết bấm vào để làm gì.',
      b:'Lặp từ khoá là nhồi từ khoá — Google coi là spam, người đọc thấy rối.',
      c:'Mã số và chữ chung chung không giúp ai hiểu nội dung trang.',
      d:'Đúng. Riêng cho trang, rõ, mô tả đúng nội dung, có nơi chốn để người gần đó nhận ra.'} },
  { type:'mcq', stem:'Đồng nghiệp: "Sửa tiêu đề xong, tháng 12 nhấp tăng 30%, vậy tiêu đề mới tạo ra 30% đó." Cần kiểm gì trước khi kết luận?',
    options:[{k:'a',t:'Không cần kiểm, nhấp tăng ngay sau khi sửa đã là bằng chứng đủ rõ'},{k:'b',t:'Kiểm xem đã thêm thẻ meta keywords chưa, vì nó có thể gây ra mức tăng'},
             {k:'c',t:'Tháng 12 vào mùa lẩu; so cùng kỳ hoặc với trang không sửa, xem CTR, vị trí'},{k:'d',t:'Chỉ cần xem số lần hiển thị; nếu hiển thị tăng thì đó là nhờ tiêu đề mới'}],
    answer:'c', why:{a:'So trước/sau không có đối chứng không tách được tác động của mùa vụ.',
      b:'Google không dùng thẻ meta keywords, nên nó không thể là nguyên nhân.',
      c:'Đúng. Mùa vụ có thể đẩy cả lượt tìm lẫn nhấp; CTR và nhóm đối chứng giúp tách phần nhờ tiêu đề.',
      d:'Hiển thị tăng có thể do nhiều người tìm lẩu hơn vào mùa lạnh, không do tiêu đề.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:kn11-06', skill:'channel', read:'6 phút', t:'Khách tìm "phở gần đây": vì sao quán bên kia đường hiện, quán mình thì không?',
  situation:'Một quán phở ở Bình Thạnh có hồ sơ Google Business Profile từ ba năm trước: giờ mở cửa cũ, số điện thoại đã đổi, 50 đánh giá, trung bình 4,2 sao, chưa từng trả lời. Facebook ghi địa chỉ "123A", Google ghi "123". Quán bên kia đường có 400 đánh giá và ảnh món mới mỗi tuần. Chủ quán hỏi có trả tiền để hiện lên trước được không. (số minh hoạ)',
  concept:{ name:'Hồ sơ doanh nghiệp trên Google và tìm kiếm địa phương',
    body:'Khi khách tìm kiểu "phở gần đây", Google hiện kết quả địa phương trên bản đồ và danh sách quán. Theo Google Business Profile Help, thứ hạng địa phương dựa chủ yếu vào ba thứ: <b>liên quan</b> (hồ sơ khớp điều người ta tìm đến đâu), <b>khoảng cách</b> (quán cách người tìm bao xa) và <b>mức độ nổi bật</b> (quán được biết đến thế nào, gồm số và điểm đánh giá, liên kết từ web khác). Google nói <b>không có cách nào yêu cầu hay trả tiền để có thứ hạng địa phương tốt hơn</b>. Việc làm được: điền đủ và đúng thông tin, giữ tên – địa chỉ – số điện thoại thống nhất ở mọi nơi, mời khách đánh giá thật và trả lời đánh giá. (kiểm 10/2026)' },
  example:'Quán sửa giờ mở cửa, số điện thoại, chọn đúng danh mục "Quán phở", thêm ảnh món và thực đơn có giá, sửa địa chỉ trên Facebook cho khớp. Sau mỗi bữa, nhân viên đưa thẻ QR mời mọi khách đánh giá — không tặng quà đổi đánh giá, không chỉ mời khách đang khen, vì chính sách nội dung của Google cấm cả hai. Quán trả lời cả đánh giá 2 sao, nói rõ đã sửa gì. Khoảng cách thì không đổi được, nên quán không mong hiện với người ở quận xa.',
  takeaway:'Điền đủ, đúng, thống nhất; mời đánh giá thật và trả lời — thứ hạng địa phương không mua được.',
  apply:'Cho hồ sơ "Phở Hạnh": Google ghi "12 Lê Lợi", Facebook ghi "12B Lê Lợi"; Google ghi mở 6h–14h nhưng thực tế 6h–21h; 30 đánh giá, 3,9 sao, 5 đánh giá 1–2 sao chưa trả lời. Viết 4 việc theo thứ tự và một câu trả lời mẫu cho đánh giá 2 sao "nước dùng nhạt". Đạt khi: (1) sửa thông tin sai trước, (2) không có việc nào đổi quà lấy đánh giá, (3) câu trả lời nhận góp ý và nói sẽ làm gì.',
  mistakes:['Tặng nước hay giảm giá để đổi lấy đánh giá — chính sách của Google cấm.','Để địa chỉ, giờ mở cửa khác nhau giữa Google, Facebook và website.'],
  q:[
  { type:'mcq', stem:'Đoán trước: quán có trả tiền được để hiện cao hơn trong danh sách quán trên bản đồ (phần không phải quảng cáo) không?',
    options:[{k:'a',t:'Có, gói Google Business trả phí sẽ đưa quán vào nhóm 3 quán đầu tiên trên bản đồ'},{k:'b',t:'Có, nếu chạy quảng cáo đủ lâu thì thứ hạng địa phương tăng theo'},
             {k:'c',t:'Có, chỉ cần xác minh hồ sơ bằng gói xác minh nhanh có thu phí'},{k:'d',t:'Không, Google nói không thể trả tiền hay yêu cầu để xếp hạng tốt hơn'}],
    answer:'d', why:{a:'Không có gói trả phí nào mua được thứ hạng địa phương.',
      b:'Quảng cáo là vị trí có nhãn riêng; nó không đẩy thứ hạng tự nhiên trên bản đồ.',
      c:'Xác minh hồ sơ miễn phí và không phải nút tăng hạng.',
      d:'Đúng. Business Profile Help ghi rõ không có cách yêu cầu hay trả tiền để có thứ hạng địa phương tốt hơn.'} },
  { type:'mcq', stem:'Quán có một buổi chiều cho hồ sơ Google. Bạn ưu tiên làm gì?',
    options:[{k:'a',t:'Sửa giờ, số điện thoại, địa chỉ cho khớp Google, Facebook, rồi trả lời các đánh giá cũ'},{k:'b',t:'Nhờ 30 người quen vào viết đánh giá 5 sao để vượt quán bên kia đường trong tháng này'},
             {k:'c',t:'Đổi tên hồ sơ thành "Phở ngon nhất Bình Thạnh" để chứa thêm từ khoá'},{k:'d',t:'Tặng một ly trà đá cho khách nào chịu đánh giá 5 sao ngay tại bàn'}],
    answer:'a', why:{a:'Đúng. Thông tin sai làm mất khách ngay (gọi số cũ, đến lúc đóng cửa); trả lời đánh giá cho khách thấy quán có nghe.',
      b:'Đánh giá ảo vi phạm chính sách nội dung của Google, có thể bị gỡ và làm hồ sơ mất uy tín.',
      c:'Nhồi từ khoá vào tên doanh nghiệp trái hướng dẫn của Google về cách đặt tên hồ sơ.',
      d:'Tặng quà đổi đánh giá bị chính sách của Google cấm.'} },
  { type:'calc', stem:'Quán có 50 đánh giá, trung bình 4,2 sao. Thêm 10 đánh giá mới, đều 5 sao. Theo cách tính trung bình đơn giản, điểm mới là bao nhiêu? (làm tròn 2 chữ số)',
    unit:'sao', ans:4.33, tol:0.01, wrong:[[4.6,'SAI_MAU_SO'],[3.67,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Tổng sao cũ = 50 × 4,2 = 210. Tổng sao mới = 10 × 5 = 50.','(210 + 50) ÷ 60 = <b>4,33 sao</b>. Lấy (4,2 + 5) ÷ 2 = 4,6 là bỏ qua số lượng đánh giá mỗi bên.'] },
  { type:'mcq', stem:'Ba yếu tố chính Google nêu cho thứ hạng địa phương là gì?',
    options:[{k:'a',t:'Giá món, số món trong thực đơn, độ dài tên quán'},{k:'b',t:'Ngân sách quảng cáo, tuổi của hồ sơ, số ảnh đã đăng'},
             {k:'c',t:'Liên quan, khoảng cách, mức độ nổi bật'},{k:'d',t:'Lượt theo dõi Facebook, lượt xem TikTok, số bài đăng'}],
    answer:'c', why:{a:'Không phải yếu tố Google nêu.',
      b:'Ngân sách quảng cáo không mua được thứ hạng; tuổi hồ sơ không phải yếu tố được nêu.',
      c:'Đúng. Relevance, distance, prominence — theo Google Business Profile Help.',
      d:'Số liệu mạng xã hội không nằm trong ba yếu tố Google nêu.'} },
  { type:'mcq', stem:'Một khách ở cách quán 6 km tìm "phở" và không thấy quán. Giải thích hợp lý nhất?',
    options:[{k:'a',t:'Khoảng cách là một yếu tố; quán gần người tìm hơn có lợi thế dù hồ sơ tốt'},{k:'b',t:'Hồ sơ của quán đã bị Google khoá vì có quá ít ảnh món ăn'},
             {k:'c',t:'Google chỉ hiện quán đã chạy quảng cáo cho người ở xa trên 5 km'},{k:'d',t:'Quán chưa có website riêng nên Google không cho hồ sơ hiện trên bản đồ tìm kiếm'}],
    answer:'a', why:{a:'Đúng. Khoảng cách gần như không đổi được; quán nên tập trung khách trong bán kính phục vụ.',
      b:'Ít ảnh không làm hồ sơ bị khoá.',
      c:'Không có quy tắc như vậy; kết quả địa phương tự nhiên không phụ thuộc quảng cáo.',
      d:'Hồ sơ không cần website vẫn hiện được trên bản đồ.'} },
  { type:'mcq', stem:'Chủ quán đề xuất: "Chỉ gửi link đánh giá cho khách nào khen, khách chê thì thôi." Vấn đề là gì?',
    options:[{k:'a',t:'Không vấn đề, đó là cách hợp lệ và phổ biến để tăng điểm trung bình'},{k:'b',t:'Chỉ mời có chọn lọc người khen bị Google cấm; nên mời cả khách chê'},
             {k:'c',t:'Vấn đề duy nhất là tốn thêm thời gian của nhân viên phục vụ bàn'},{k:'d',t:'Google chỉ tính đánh giá có ảnh, nên việc chọn khách không có tác dụng'}],
    answer:'b', why:{a:'Phổ biến không có nghĩa hợp lệ; chính sách của Google cấm chọn lọc mời đánh giá tốt.',
      b:'Đúng. Chính sách nội dung trên Maps cấm doanh nghiệp chỉ mời đánh giá tích cực một cách có chọn lọc.',
      c:'Thời gian là chuyện nhỏ; rủi ro vi phạm chính sách mới là chuyện lớn.',
      d:'Đánh giá không cần ảnh vẫn được tính.'} },
  { type:'mcq', stem:'Một đánh giá 2 sao: "Chờ 25 phút mới có phở." Cách trả lời nào tốt nhất?',
    options:[{k:'a',t:'Xin khách gỡ đánh giá, đổi lại quán tặng một bát phở miễn phí'},{k:'b',t:'Giải thích hôm đó quá đông khách nên lỗi không nằm ở phía quán'},
             {k:'c',t:'Không trả lời để đánh giá xấu không bị đẩy lên cao hơn trong danh sách'},{k:'d',t:'Cảm ơn, nhận lỗi, nói quán đã thêm người giờ cao điểm, mời quay lại'}],
    answer:'d', why:{a:'Đổi quà lấy việc gỡ hay sửa đánh giá cũng là đổi lợi ích lấy đánh giá.',
      b:'Đổ lỗi làm người đọc sau thấy quán không nghe góp ý.',
      c:'Im lặng cho người đọc sau thấy lời chê không được xử lý.',
      d:'Đúng. Người đọc sau thấy quán nghe và đã sửa — điều đó nói nhiều hơn một ngôi sao.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:kn11-07', skill:'measure', read:'6 phút', t:'Vị trí trung bình tụt từ 8 xuống 15 — website đang tệ đi?',
  situation:'Shop mỹ phẩm online xem Search Console tháng 9: 12.000 lần hiển thị, 360 nhấp, vị trí trung bình 15. Tháng 8 vị trí trung bình là 8, với 5.000 lần hiển thị và 300 nhấp. Sếp hoảng: "Tụt hạng gần gấp đôi!". Trong GA4 tháng 9, nhóm Organic Search có 330 phiên, Paid Search có 900 phiên. (số minh hoạ)',
  concept:{ name:'Đo SEO bằng Search Console và GA4',
    body:'Search Console đo phần trước khi khách vào site. <b>Hiển thị</b>: số lần link của bạn xuất hiện trong kết quả. <b>Nhấp</b>: số lần người dùng bấm từ Google sang site. <b>CTR</b> = nhấp ÷ hiển thị. <b>Vị trí trung bình</b>: vị trí cao nhất của link bạn trong mỗi lần hiện, rồi lấy trung bình; Google lưu ý đây không phải thứ hạng của bạn cho một tìm kiếm cụ thể, và quảng cáo không chiếm vị trí. GA4 đo phần sau khi khách vào site; nhóm kênh mặc định tách <b>Organic Search</b> (kết quả tự nhiên) và <b>Paid Search</b> (quảng cáo tìm kiếm). Nhấp và phiên là hai thứ khác nhau, nên số lệch nhau là bình thường. (Search Console Help, kiểm 10/2026)' },
  example:'Tháng 9 shop có thêm nhiều trang bắt đầu hiện cho từ khoá rộng ở vị trí 20–50. Những lần hiện mới này kéo trung bình xuống, dù các từ khoá cũ có thể vẫn ở chỗ cũ — phải lọc theo từng truy vấn mới biết. CTR tháng 9 = 360 ÷ 12.000 = 3%; tháng 8 = 300 ÷ 5.000 = 6%. Số nhấp vẫn tăng thêm 60. Đọc vị trí trung bình cùng hiển thị và nhấp, lọc theo truy vấn hoặc trang. Còn 900 phiên Paid Search là quảng cáo, không phải thành quả SEO.',
  takeaway:'Đọc vị trí trung bình cùng hiển thị, nhấp và từng truy vấn; tách organic khỏi paid trước khi báo cáo SEO.',
  apply:'Cho bảng hai truy vấn tháng 9: "kem chống nắng da dầu" 2.000 hiển thị, 120 nhấp, vị trí 4; "kem chống nắng" 10.000 hiển thị, 240 nhấp, vị trí 22. Tính CTR từng dòng và viết 2 câu giải thích cho sếp vì sao vị trí trung bình cả site tụt. Đạt khi: (1) có hai CTR đúng, (2) giải thích bằng truy vấn mới ở vị trí thấp, không kết luận "tụt hạng".',
  mistakes:['Báo cáo "SEO tăng" bằng tổng truy cập từ Google, gộp cả quảng cáo tìm kiếm.','Hoảng khi vị trí trung bình tụt mà không xem hiển thị và từng truy vấn.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vị trí trung bình từ 8 thành 15 trong khi hiển thị tăng từ 5.000 lên 12.000. Giải thích khả dĩ nhất?',
    options:[{k:'a',t:'Google phạt site nên từ khoá nào cũng tụt khoảng 7 bậc'},{k:'b',t:'Site hiện thêm cho nhiều truy vấn mới ở vị trí thấp, kéo trung bình xuống'},
             {k:'c',t:'Search Console tính sai nên nên bỏ qua chỉ số vị trí'},{k:'d',t:'Đối thủ chạy quảng cáo mạnh tay nên đẩy kết quả tự nhiên của site xuống 7 bậc'}],
    answer:'b', why:{a:'Nếu bị phạt, hiển thị và nhấp thường giảm; ở đây cả hai đều tăng.',
      b:'Đúng. Hiển thị tăng mạnh cùng lúc vị trí trung bình tụt là dấu hiệu của truy vấn mới ở vị trí thấp.',
      c:'Số không sai; chỉ là trung bình gộp nhiều truy vấn rất khác nhau.',
      d:'Theo Google, quảng cáo không chiếm vị trí trong cách tính của Search Console.'} },
  { type:'mcq', stem:'Sếp muốn báo cáo "tụt hạng gần gấp đôi". Bạn đề xuất làm gì trước?',
    options:[{k:'a',t:'Đồng ý báo cáo, rồi thuê agency kéo vị trí trung bình của site về lại mức 8'},{k:'b',t:'Xoá các trang mới vì chính chúng làm vị trí trung bình xấu đi'},
             {k:'c',t:'Lọc theo từng truy vấn và trang, so vị trí và nhấp của nhóm truy vấn cũ'},{k:'d',t:'Chuyển sang GA4 vì GA4 có vị trí trung bình chính xác hơn'}],
    answer:'c', why:{a:'Báo cáo sai bản chất rồi chi tiền sửa một vấn đề có thể không tồn tại.',
      b:'Xoá trang đang mang thêm hiển thị và nhấp để làm đẹp một con số trung bình là phản tác dụng.',
      c:'Đúng. Tách nhóm truy vấn cũ ra mới biết có tụt thật hay chỉ là trung bình bị pha.',
      d:'GA4 không đo vị trí trên trang kết quả; đó là việc của Search Console.'} },
  { type:'calc', stem:'Tháng 9 có 12.000 lần hiển thị và 360 nhấp. CTR là bao nhiêu phần trăm?',
    unit:'%', ans:3, tol:0.01, wrong:[[33.3,'SAI_MAU_SO'],[0.03,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['CTR = nhấp ÷ hiển thị.','360 ÷ 12.000 = 0,03 = <b>3%</b>. Chia ngược 12.000 ÷ 360 ra 33,3; quên đổi sang phần trăm ra 0,03.'] },
  { type:'mcq', stem:'Trong GA4, 900 phiên Paid Search có nên tính vào kết quả SEO không?',
    options:[{k:'a',t:'Có, vì đều đến từ Google nên đều là thành quả của SEO'},{k:'b',t:'Có, nếu sau đó khách quay lại qua kết quả tự nhiên'},
             {k:'c',t:'Không, đó là quảng cáo tìm kiếm; SEO là nhóm Organic Search'},{k:'d',t:'Chỉ tính một nửa vì quảng cáo có phần nhờ SEO hỗ trợ'}],
    answer:'c', why:{a:'Cùng đến từ Google nhưng một bên trả tiền mỗi nhấp, một bên không; gộp lại là thổi phồng SEO.',
      b:'Phiên quay lại qua kết quả tự nhiên đã được tính ở Organic Search; phiên trả tiền vẫn là trả tiền.',
      c:'Đúng. Nhóm kênh mặc định của GA4 tách hai nhóm này; báo cáo SEO chỉ dùng Organic Search.',
      d:'Không có quy tắc chia đôi; hai kênh được đo riêng.'} },
  { type:'mcq', stem:'Search Console báo 360 nhấp, GA4 báo 330 phiên Organic Search từ Google. Cách hiểu đúng?',
    options:[{k:'a',t:'Một trong hai công cụ bị lỗi, cần báo Google để sửa số'},{k:'b',t:'GA4 đúng, Search Console sai vì nó đếm lẫn cả quảng cáo'},
             {k:'c',t:'Search Console đúng, chênh 30 là do đối thủ bấm ảo vào site'},{k:'d',t:'Nhấp và phiên là hai thứ khác nhau; chặn đo, thoát sớm làm lệch'}],
    answer:'d', why:{a:'Lệch nhỏ là bình thường; không phải lỗi.',
      b:'Search Console chỉ đếm nhấp từ kết quả Google, không gồm quảng cáo.',
      c:'Không có dữ kiện về bấm ảo; lệch nhỏ có lời giải thích bình thường hơn.',
      d:'Đúng. Có người bấm rồi thoát trước khi trang tải, có người chặn đo lường; hai công cụ đếm hai thứ khác nhau.'} },
  { type:'mcq', stem:'Theo Google, khi link của bạn hiện ở hai chỗ trên cùng một trang kết quả, Search Console ghi vị trí thế nào?',
    options:[{k:'a',t:'Lấy vị trí cao nhất trong các chỗ link đó xuất hiện'},{k:'b',t:'Cộng hai vị trí lại rồi chia đôi để lấy trung bình'},
             {k:'c',t:'Lấy vị trí thấp nhất để báo cáo cho thận trọng'},{k:'d',t:'Không ghi vì link hiện hai lần bị coi là trùng lặp'}],
    answer:'a', why:{a:'Đúng. Search Console Help: giá trị vị trí là vị trí cao nhất (topmost) mà link của bạn chiếm.',
      b:'Không chia đôi; chỉ lấy vị trí cao nhất.',
      c:'Ngược lại: lấy vị trí cao nhất.',
      d:'Vẫn được ghi, với vị trí cao nhất.'} },
  { type:'mcq', stem:'Trang A: 20.000 hiển thị, CTR 1%, vị trí 9. Trang B: 2.000 hiển thị, CTR 8%, vị trí 3. Sếp muốn dồn sức sửa B vì "CTR cao hơn". Nhận định nào hợp lý?',
    options:[{k:'a',t:'Đúng, CTR cao hơn nghĩa là trang tốt hơn, nên dồn thời gian và tiền cho trang B'},{k:'b',t:'Sai, chỉ nên nhìn vị trí: A ở vị trí 9 nên bỏ trang này đi'},
             {k:'c',t:'Hai trang mang nhấp gần nhau; A còn nhiều chỗ tăng nếu tiêu đề, vị trí khá hơn'},{k:'d',t:'Không so được gì vì hai trang có số lần hiển thị khác nhau'}],
    answer:'c', why:{a:'A mang 200 nhấp, B 160 nhấp; CTR cao ở vị trí 3 là chuyện thường, chưa nói trang nào đáng sửa hơn.',
      b:'A đang mang nhiều nhấp hơn B; bỏ nó là mất nhấp.',
      c:'Đúng. 20.000 × 1% = 200 và 2.000 × 8% = 160; A có lượng hiển thị lớn, tăng CTR một chút là thêm nhiều nhấp.',
      d:'So được, khi quy về số nhấp và xem còn bao nhiêu chỗ để tăng.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:kn11-08', skill:'measure', read:'6 phút', t:'Bỏ 12 triệu làm nội dung SEO — bao lâu hoàn vốn, và cách nào đốt tiền?',
  situation:'Shop bán dụng cụ làm bánh online định chi 12 triệu đồng viết 6 trang hướng dẫn kỹ, nhắm một cụm từ khoá tổng 5.000 lượt tìm/tháng. Một agency khác chào: "500 backlink giá 3 triệu, 2 tuần lên top". Shop đang trả quảng cáo tìm kiếm khoảng 3.000đ mỗi nhấp. Đơn trung bình 500.000đ, lãi gộp 30%, tỉ lệ ra đơn 2%. (số minh hoạ)',
  concept:{ name:'Ước hoàn vốn nội dung SEO, ghi rõ giả định',
    body:'Ước theo chuỗi: <b>nhấp kỳ vọng</b> = lượng tìm × CTR giả định ở vị trí bạn nghĩ có thể đạt; <b>đơn</b> = nhấp × tỉ lệ ra đơn; <b>lãi gộp mỗi tháng</b> = đơn × lãi gộp mỗi đơn; <b>thời gian hoàn vốn</b> = chi phí ÷ lãi gộp mỗi tháng, tính từ khi trang có nhấp đều, cộng thêm thời gian chờ. Phép so phụ: <b>giá trị thay thế quảng cáo</b> = nhấp tự nhiên × giá mỗi nhấp (CPC) bạn đang trả; nó cho biết phải trả bao nhiêu để mua cùng số nhấp, không phải lợi nhuận. Google xếp mua bán liên kết để xếp hạng và nhồi từ khoá vào spam; site vi phạm có thể bị hạ hạng hoặc không xuất hiện. (Google Search Central, Spam policies, kiểm 10/2026)' },
  example:'Giả định CTR 8% (minh hoạ, không phải số của Google): 5.000 × 8% = 400 nhấp/tháng. Đơn = 400 × 2% = 8. Lãi gộp mỗi đơn = 500.000 × 30% = 150.000đ, tức 1,2 triệu/tháng. Hoàn vốn = 12 ÷ 1,2 = 10 tháng sau khi trang có nhấp đều; nếu mất 4 tháng để lên, tổng khoảng 14 tháng. Giá trị thay thế quảng cáo = 400 × 3.000đ = 1,2 triệu/tháng — trùng số ở đây là tình cờ. Gói 500 backlink là mua liên kết để thao túng thứ hạng: rủi ro bị hạ hạng.',
  takeaway:'Ước hoàn vốn bằng lãi gộp, ghi rõ CTR là giả định, cộng thời gian chờ; tránh mua link và nhồi từ khoá.',
  apply:'Cho: cụm từ khoá 3.000 lượt tìm/tháng, CTR giả định 6%, tỉ lệ ra đơn 3%, đơn 400.000đ, lãi gộp 25%, chi phí nội dung 9 triệu, 3 tháng chờ trang có nhấp. Tính tổng thời gian hoàn vốn và viết 1 câu nêu giả định yếu nhất. Đạt khi: (1) dùng lãi gộp, không dùng doanh thu, (2) cộng thời gian chờ, (3) nói rõ CTR là số minh hoạ cần thay bằng số thật.',
  mistakes:['Mua gói backlink hàng loạt để "lên top nhanh" — Google xếp vào spam liên kết.','Tính hoàn vốn bằng doanh thu và quên mấy tháng chờ trang có nhấp.'],
  q:[
  { type:'mcq', stem:'Đoán trước: gói "500 backlink giá 3 triệu, 2 tuần lên top" có rủi ro gì lớn nhất?',
    options:[{k:'a',t:'Mua liên kết để thao túng thứ hạng là spam theo Google; trang có thể bị hạ'},{k:'b',t:'Ít rủi ro, vì Google khó phân biệt liên kết mua với liên kết tự nhiên'},
             {k:'c',t:'Rủi ro chính chỉ là mất 3 triệu nếu sau 2 tuần trang vẫn chưa lên top'},{k:'d',t:'Chỉ rủi ro khi backlink đến từ website nước ngoài, khác ngôn ngữ với shop'}],
    answer:'a', why:{a:'Đúng. Spam policies nêu "mua bán liên kết để xếp hạng" là spam liên kết; site vi phạm có thể bị hạ hoặc không xuất hiện.',
      b:'Google có hệ thống và đội ngũ riêng xử lý spam liên kết; đặt cược vào việc "khó phát hiện" là rủi ro lớn.',
      c:'Mất 3 triệu là phần nhỏ; rủi ro lớn là trang bị hạ hạng.',
      d:'Nguồn trong nước hay nước ngoài đều vậy; vấn đề là mua liên kết để thao túng.'} },
  { type:'mcq', stem:'Shop phải chọn giữa 12 triệu làm nội dung và 3 triệu backlink + 9 triệu quảng cáo. Bạn chọn và trình bày thế nào?',
    options:[{k:'a',t:'Chọn backlink vì rẻ hơn 4 lần và cho kết quả nhanh hơn nội dung'},{k:'b',t:'Chọn 12 triệu nội dung và hứa với sếp trang sẽ lên top trong 1 tháng'},
             {k:'c',t:'Bỏ cả hai, vì SEO không đo được nên không đáng để bỏ tiền vào'},{k:'d',t:'Bỏ backlink; chọn nội dung, ghi rõ giả định, giữ quảng cáo trong lúc chờ'}],
    answer:'d', why:{a:'Rẻ và nhanh trên giấy, nhưng đổi lấy rủi ro bị hạ hạng cho cả site.',
      b:'Không ai hứa được thứ hạng hay mốc 1 tháng; hứa vậy là tự đặt bẫy cho mình.',
      c:'SEO đo được bằng Search Console và GA4; bỏ cả hai là bỏ kênh tích luỹ.',
      d:'Đúng. Đầu tư bền, minh bạch giả định, và không để hụt đơn trong thời gian chờ.'} },
  { type:'calc', stem:'Cụm từ khoá 5.000 lượt tìm/tháng, CTR giả định 8% (minh hoạ), tỉ lệ ra đơn 2%, đơn 500.000đ, lãi gộp 30%. Chi phí nội dung 12 triệu. Bao nhiêu tháng hoàn vốn, tính từ khi trang có nhấp đều?',
    unit:'tháng', ans:10, tol:0.05, wrong:[[3,'HOAN_VON_TINH_DOANH_THU'],[0.1,'SAI_TINH_TOAN']], errors:['HOAN_VON_TINH_DOANH_THU'],
    steps:['Nhấp = 5.000 × 8% = 400; đơn = 400 × 2% = 8.','Lãi gộp/tháng = 8 × 500.000 × 30% = 1.200.000đ.','Hoàn vốn = 12.000.000 ÷ 1.200.000 = <b>10 tháng</b>. Dùng doanh thu 4 triệu/tháng ra 3 tháng là quên rằng 70% doanh thu là giá vốn.'] },
  { type:'mcq', stem:'Shop có 400 nhấp tự nhiên/tháng, đang trả 3.000đ mỗi nhấp quảng cáo. Con số 1,2 triệu (400 × 3.000đ) nên hiểu thế nào?',
    options:[{k:'a',t:'Là lợi nhuận ròng mà SEO mang về cho shop mỗi tháng sau khi trừ chi phí'},{k:'b',t:'Là tiền phải trả để mua cùng số nhấp bằng quảng cáo, không phải lãi'},
             {k:'c',t:'Là doanh thu bán hàng mà SEO tạo ra mỗi tháng'},{k:'d',t:'Là khoản Google hoàn lại cho shop mỗi tháng vì website có nhấp tự nhiên'}],
    answer:'b', why:{a:'Lãi phải tính từ đơn và lãi gộp; con số này không liên quan tới đơn.',
      b:'Đúng. Đó là giá trị thay thế quảng cáo — hữu ích để so, nhưng không phải lợi nhuận.',
      c:'Doanh thu = đơn × giá trị đơn, không phải nhấp × CPC.',
      d:'Google không trả tiền cho nhấp tự nhiên.'} },
  { type:'mcq', stem:'Shop muốn trang lên nhanh nên lặp "dụng cụ làm bánh" 40 lần trong một bài 800 chữ. Điều gì có thể xảy ra?',
    options:[{k:'a',t:'Google hiểu chủ đề rõ hơn nên bài lên top nhanh hơn'},{k:'b',t:'Không sao, miễn là các lần lặp được tô đậm cho dễ thấy'},
             {k:'c',t:'Người đọc thấy mệt, và Google coi nhồi từ khoá là spam'},{k:'d',t:'Google chỉ đếm lần xuất hiện đầu tiên nên vô hại'}],
    answer:'c', why:{a:'Google hiểu chủ đề qua nội dung tổng thể; lặp từ không làm hiểu rõ hơn.',
      b:'Tô đậm không biến nhồi từ khoá thành hợp lệ.',
      c:'Đúng. Spam policies định nghĩa nhồi từ khoá là chèn từ hoặc số vào trang để thao túng thứ hạng.',
      d:'Nhồi từ khoá là vi phạm chính sách, không phải chuyện đếm lần đầu.'} },
  { type:'mcq', stem:'Kế hoạch ghi gọn: "Hoàn vốn 10 tháng." Thiếu gì khiến con số này dễ gây hiểu lầm?',
    options:[{k:'a',t:'Thiếu thời gian chờ trang có nhấp đều, và chưa ghi CTR 8% là giả định'},{k:'b',t:'Thiếu số backlink cần mua thêm để bảo đảm trang giữ được thứ hạng'},
             {k:'c',t:'Thiếu thuế giá trị gia tăng nên phải nhân kết quả thêm với 1,1'},{k:'d',t:'Thiếu bước đổi lãi gộp thành doanh thu để con số được đầy đủ hơn'}],
    answer:'a', why:{a:'Đúng. 10 tháng tính từ khi trang có nhấp; cộng 4 tháng chờ là khoảng 14. CTR 8% là minh hoạ, sai nó thì sai cả chuỗi.',
      b:'Mua backlink là spam; không bảo đảm được gì.',
      c:'Thuế không phải chỗ gây hiểu lầm chính; thiếu thời gian chờ và giả định mới là.',
      d:'Ngược lại: hoàn vốn phải dùng lãi gộp, dùng doanh thu mới sai.'} },
  { type:'mcq', stem:'Sau 2 tuần chưa thấy nhấp, sếp muốn dừng. Bạn phản hồi thế nào?',
    options:[{k:'a',t:'Dừng ngay vì 2 tuần chưa có lượt nhấp nào là đủ để thấy SEO đã thất bại'},{k:'b',t:'Mua backlink để có kết quả kịp trước buổi họp tuần sau'},
             {k:'c',t:'Viết thêm 20 bài ngắn ngay trong tuần này để tăng tốc độ lên top cho cả site'},{k:'d',t:'Google nói có thể mất vài tháng; theo dõi hiển thị, đặt mốc xem lại 3–4 tháng'}],
    answer:'d', why:{a:'Google nói thay đổi có thể mất từ vài giờ đến vài tháng; 2 tuần chưa đủ để kết luận.',
      b:'Mua liên kết là spam; đổi kết quả ngắn hạn lấy rủi ro hạ hạng.',
      c:'Bài ngắn làm vội lặp lại lỗi nội dung mỏng của bài 4.',
      d:'Đúng. Hiển thị trong Search Console thường nhích trước nhấp; đặt mốc xem lại rõ ràng thay vì hứa ngày lên top.'} }
  ] }

] });
